import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import '../services/club_activity_service.dart';

class ClubActivitiesPage extends StatelessWidget { final String clubDocId; final bool canCreate; const ClubActivitiesPage({super.key,required this.clubDocId,required this.canCreate}); Future<void> _create(BuildContext context) async {final t=TextEditingController(),d=TextEditingController();DateTime date=DateTime.now().add(const Duration(days:1));await showModalBottomSheet(context:context,isScrollControlled:true,backgroundColor:const Color(0xFF18181F),builder:(c)=>StatefulBuilder(builder:(c,set)=>Padding(padding:EdgeInsets.only(left:20,right:20,top:20,bottom:MediaQuery.of(c).viewInsets.bottom+20),child:Column(mainAxisSize:MainAxisSize.min,children:[const Text('Create Activity',style:TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.bold)),TextField(controller:t,style:const TextStyle(color:Colors.white),decoration:const InputDecoration(labelText:'Title',labelStyle:TextStyle(color:Colors.white54))),TextField(controller:d,style:const TextStyle(color:Colors.white),decoration:const InputDecoration(labelText:'Description',labelStyle:TextStyle(color:Colors.white54))),ListTile(title:Text('${date.day}/${date.month}/${date.year}',style:const TextStyle(color:Colors.white)),trailing:const Icon(Icons.calendar_month,color:Colors.white70),onTap:()async{final x=await showDatePicker(context:c,firstDate:DateTime.now(),lastDate:DateTime.now().add(const Duration(days:365)),initialDate:date);if(x!=null)set((){date=DateTime(x.year,x.month,x.day,18);});}),ElevatedButton(onPressed:()async{try{await ClubActivityService.createActivity(clubId:clubDocId,uid:FirebaseAuth.instance.currentUser?.uid??'',title:t.text,description:d.text,date:date);if(c.mounted)Navigator.pop(c);}catch(e){ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));}},child:const Text('Create'))]))));}
 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.transparent,floatingActionButton:canCreate?FloatingActionButton(onPressed:()=>_create(context),child:const Icon(Icons.add)):null,body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:ClubActivityService.watchActivities(clubDocId),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final now=DateTime.now();return ListView(padding:const EdgeInsets.all(16),children:s.data!.docs.map((doc){final x=doc.data();final date=(x['date'] as Timestamp?)?.toDate()??now;final participants=List<String>.from(x['participants']??const[]);final joined=participants.contains(FirebaseAuth.instance.currentUser?.uid);final completed=date.isBefore(now);return Card(color:const Color(0xFF18181F),child:ListTile(title:Text(x['title']??'',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.bold)),subtitle:Text('${x['description']??''}\n${date.day}/${date.month}/${date.year} • ${completed?'Completed':'Upcoming'}\n${participants.length} participants',style:const TextStyle(color:Colors.white60,height:1.4)),trailing:completed?const Icon(Icons.check_circle,color:Colors.white38):TextButton(onPressed:()async{final uid=FirebaseAuth.instance.currentUser?.uid??'';if(joined){await ClubActivityService.leave(clubId:clubDocId,activityId:doc.id,uid:uid);}else{await ClubActivityService.join(clubId:clubDocId,activityId:doc.id,uid:uid);}},child:Text(joined?'Leave':'Join')),));}).toList());}));
}
